const { chromium } = require('@playwright/test')
const BASE = 'http://127.0.0.1:8095'
const EDGE = 'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe'
const crypto = require('crypto')
const key = Buffer.from('A-16-Byte-keyValA-16-Byte-keyVal', 'utf8')
const iv = Buffer.from('A-16-Byte-String', 'utf8')
const c = crypto.createCipheriv('aes-256-cbc', key, iv)
const enc = Buffer.concat([c.update('Zs@2026Aa!', 'utf8'), c.final()]).toString('base64')

;(async () => {
  const browser = await chromium.launch({ executablePath: EDGE, headless: true })
  const ctx = await browser.newContext({ viewport: { width: 390, height: 844 } })
  const login = await ctx.request.post(BASE + '/api/v2.0/security/auth/login', {
    headers: { 'Content-Type': 'application/json', 'zhi-project-id': 'suzhufang' },
    data: { username: 'zsbase', password: enc },
  })
  const body = await login.json()
  const token = body?.data?.accessToken
  console.log(`LOGIN code=${body?.code} token=${token ? token.length + ' chars' : 'NONE'}`)
  if (!token) { console.log('SKIP: no token'); await browser.close(); process.exit(1) }

  await ctx.addInitScript(([k, v]) => {
    try { window.localStorage.setItem(k, v) } catch {}
  }, ['flood-token-v1', token])

  for (const [name, route] of [['首页', '/#/pages/home/index'], ['我的', '/#/pages/mine/index'], ['任务中心', '/#/pages/portal/list/index?type=task']]) {
    const page = await ctx.newPage()
    const apiCalls = []
    const errs = []
    page.on('request', r => { if (r.url().includes('/api/')) apiCalls.push(r.url().replace(BASE, '').split('?')[0]) })
    page.on('pageerror', e => errs.push(e.message))
    await page.goto(BASE + route, { waitUntil: 'domcontentloaded' })
    await page.waitForTimeout(2500)
    const text = (await page.locator('body').innerText().catch(() => '')).replace(/\s+/g, ' ').slice(0, 120)
    console.log(`\n[${name}] errs=${errs.length} text="${text}"`)
    console.log(`  API calls (${apiCalls.length}): ${[...new Set(apiCalls)].join(', ')}`)
    errs.forEach(e => console.log('  PAGEERROR ' + e))
    await page.close()
  }
  await browser.close()
})().catch(e => { console.error('FATAL', e); process.exit(2) })

const { chromium } = require('@playwright/test')
const BASE = 'http://127.0.0.1:8095'
const EDGE = 'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe'
