const c = crypto.createCipheriv('aes-256-cbc', Buffer.from('A-16-Byte-keyValA-16-Byte-keyVal'), Buffer.from('A-16-Byte-String'))
const enc = Buffer.concat([c.update('Zs@2026Aa!', 'utf8'), c.final()]).toString('base64')
;(async () => {
  const browser = await chromium.launch({ executablePath: EDGE, headless: true })
  const ctx = await browser.newContext({ viewport: { width: 390, height: 844 } })
  const login = await ctx.request.post(BASE + '/api/v2.0/security/auth/login', {
    headers: { 'Content-Type': 'application/json', 'zhi-project-id': 'suzhufang' },
    data: { username: 'zsbase', password: enc },
  })
  const token = (await login.json()).data.accessToken
  await ctx.addInitScript(([k, v]) => { try { window.localStorage.setItem(k, v) } catch {} }, ['flood-token-v1', token])
  const page = await ctx.newPage()
  page.on('response', async r => {
    if (r.url().includes('/flowable/task/taskCount') || r.url().includes('/msg/msg/msgNum')) {
      let body = ''
      try { body = (await r.text()).slice(0, 200) } catch {}
      console.log(`RESP ${r.status()} ${r.url().replace(BASE, '')} => ${body}`)
    }
  })
  await page.goto(BASE + '/#/pages/home/index', { waitUntil: 'domcontentloaded' })
  await page.waitForTimeout(3000)
  const direct = await page.evaluate(async () => {
    const t = localStorage.getItem('flood-token-v1')
    const r = await fetch('/api/v2.0/flowable/task/taskCount', { headers: { 'zhi-project-id': 'suzhufang', 'Authorization': 'Bearer ' + t } })
    return `${r.status} ${(await r.text()).slice(0, 160)}`
  })
  console.log('DIRECT taskCount => ' + direct)
  const todoText = await page.locator('.todo-badge').innerText().catch(() => '(none)')
  console.log('HOME todo-badge => ' + todoText)
  await browser.close()
})().catch(e => { console.error('FATAL', e); process.exit(2) })

